const test=require('node:test'),assert=require('node:assert/strict');
const C=require('../public/core.js');const mod=import('../adapters/free-ranking-review.mjs');
function table(state='official-reviewed'){const t={tour:'WTA',rankingDate:'2026-10-05',rows:Array.from({length:100},(_,i)=>({rank:i+1,playerId:'p'+i,points:2000-i,change:0}))};t.evidenceReview={state,rankingDate:t.rankingDate,checkedAt:'2026-10-11T13:04:59.217Z',sourceUrl:'https://www.wtatennis.com/rankings/singles',rowCount:100,reviewedRows:t.rows.map(x=>[x.rank,x.playerId,x.points,x.change])};return t;}
test('the exact officially checked 100-row table has a scoped review',()=>{const t=table(),before=structuredClone(t);assert.equal(C.rankingReview(t).label,'本期官方核对');assert.deepEqual(t,before);});
test('a newer issue cannot inherit an earlier official review',()=>{const t=table();t.rankingDate='2026-10-12';assert.equal(C.rankingReview(t),null);});
test('same-week corrections invalidate the old review rather than inheriting its badge',()=>{for(const key of ['rank','points','change','playerId']){const t=table();t.rows[0][key]=key==='playerId'?'other':999;assert.equal(C.rankingReview(t),null,key);}});
test('an incomplete or duplicate table can never display official verification',()=>{const t=table();t.rows.pop();assert.equal(C.rankingReview(t),null);const u=table();u.rows[1].playerId=u.rows[0].playerId;u.evidenceReview.reviewedRows=u.rows.map(x=>[x.rank,x.playerId,x.points,x.change]);assert.equal(C.rankingReview(u),null);});
test('missing evidence and unsafe source URLs do not create official badges',()=>{assert.equal(C.rankingReview(null),null);for(const field of ['checkedAt','sourceUrl','reviewedRows']){const t=table();delete t.evidenceReview[field];assert.equal(C.rankingReview(t),null);}const t=table();t.evidenceReview.sourceUrl='javascript:alert(1)';assert.equal(C.rankingReview(t),null);});
test('conflict counts require actual differing values in this exact table',()=>{const t=table('conflict');t.evidenceReview.conflicts=[{playerId:'p0',current:{rank:1,points:2000},candidate:{rank:1,points:2100}}];assert.equal(C.rankingReview(t).affectedCount,1);t.evidenceReview.conflicts[0].candidate.points=2000;assert.equal(C.rankingReview(t),null);});
test('conflicts for another player or duplicate conflicts fail closed',()=>{const t=table('conflict'),c={playerId:'p0',current:{rank:1,points:2000},candidate:{rank:1,points:2100}};t.evidenceReview.conflicts=[c,c];assert.equal(C.rankingReview(t),null);c.playerId='absent';t.evidenceReview.conflicts=[c];assert.equal(C.rankingReview(t),null);});
test('date-filter URLs retain the free allowlist and validate exact calendar dates',async()=>{const m=await mod;assert.equal(m.rankingURL('WTA',null,{date:'2026-10-05'}),'https://api.balldontlie.io/wta/v1/rankings?per_page=100&date=2026-10-05');for(const date of ['2026-02-30','https://other.test','2026-10-05&key=abc'])assert.throws(()=>m.rankingURL('WTA',null,{date}));});
test('a successful response with an unhonored requested date remains rejected',async()=>{const m=await mod,t=table(),players=t.rows.map((r,i)=>({id:r.playerId,tour:'WTA',country:'FRA',enName:'First'+i+' Last'+i}));const rows=t.rows.map((r,i)=>({rank:r.rank,points:r.points,movement:r.change,ranking_date:'2026-09-28',player:{id:i+1,full_name:players[i].enName,country_code:'FRA'}}));const review=m.inspectRankingPages([{data:rows}],'WTA',{rankings:[t],players},{today:'2026-10-11',requestedDate:'2026-10-05'});assert.ok(review.problems.includes('requested-date-not-honored'));assert.equal(review.rankingDate,'2026-09-28');assert.equal(review.eligibleForEditorialReview,false);});
test('an official representation is not replaced to accommodate a different provider country',async()=>{const m=await mod,t=table(),players=t.rows.map((r,i)=>({id:r.playerId,tour:'WTA',country:'FRA',enName:'First'+i+' Last'+i}));const rows=t.rows.map((r,i)=>({rank:r.rank,points:r.points,movement:r.change,ranking_date:t.rankingDate,player:{id:i+1,full_name:players[i].enName,country_code:i===0?'RUS':'FRA'}}));const current={rankings:[t],players},before=structuredClone(current);const r=m.inspectRankingPages([{data:rows}],'WTA',current,{today:'2026-10-11'});assert.equal(r.rows[0].playerId,null);assert.ok(r.problems.includes('unresolved-identities'));assert.deepEqual(current,before);});
